create schema if not exists taxi_private;
revoke all on schema taxi_private from public;
grant usage on schema taxi_private to authenticated;
create table taxi_private.owners(id uuid primary key references auth.users(id) on delete cascade);
alter table taxi_private.owners enable row level security;
revoke all on taxi_private.owners from public,anon,authenticated;
create function taxi_private.is_owner() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from taxi_private.owners where id=auth.uid())$$;
create function taxi_private.email_verified() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null and is_anonymous=false)$$;
revoke all on function taxi_private.is_owner(),taxi_private.email_verified() from public,anon,authenticated;
grant execute on function taxi_private.is_owner(),taxi_private.email_verified() to authenticated;
create table public.driver_profiles(id uuid primary key references auth.users(id) on delete cascade,username text not null check(username ~ '^[A-Za-z0-9_]{3,32}$'),full_name text not null check(char_length(full_name) between 2 and 120),status text not null default 'pending' check(status in ('pending','approved','rejected','suspended')),created_at timestamptz not null default now());
create unique index driver_username_unique on public.driver_profiles(lower(username));
alter table public.driver_profiles enable row level security;
revoke all on public.driver_profiles from public,anon,authenticated;
grant select,insert(id,username,full_name),update(status) on public.driver_profiles to authenticated;
create policy read_profile on public.driver_profiles for select to authenticated using(id=(select auth.uid()) or (select taxi_private.is_owner()));
create policy register_profile on public.driver_profiles for insert to authenticated with check(id=(select auth.uid()) and status='pending' and (select taxi_private.email_verified()));
create policy review_profile on public.driver_profiles for update to authenticated using((select taxi_private.is_owner())) with check((select taxi_private.is_owner()));
create table public.driver_data(user_id uuid primary key references auth.users(id) on delete cascade,payload jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
alter table public.driver_data enable row level security;
revoke all on public.driver_data from public,anon,authenticated;
grant select,insert,update,delete on public.driver_data to authenticated;
create policy own_approved_data on public.driver_data for all to authenticated using(user_id=(select auth.uid()) and ((select taxi_private.is_owner()) or exists(select 1 from public.driver_profiles p where p.id=(select auth.uid()) and p.status='approved'))) with check(user_id=(select auth.uid()) and ((select taxi_private.is_owner()) or exists(select 1 from public.driver_profiles p where p.id=(select auth.uid()) and p.status='approved')));
